// R143 synthetic restore journal; no production imports or data.
import test from 'node:test';
import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const a={owner:'one',character:'hero'}, b={owner:'one',character:'alt'}, c={owner:'two',character:'hero'};
const key=p=>JSON.stringify([p.owner,p.character]);
const encode=JSON.stringify, decode=JSON.parse;
function open(path){const db=new DatabaseSync(path);db.exec('PRAGMA busy_timeout=100; PRAGMA synchronous=FULL');return db;}
function tx(db,fn){db.exec('BEGIN IMMEDIATE');try{const result=fn();db.exec('COMMIT');return result;}catch(e){if(db.isTransaction)db.exec('ROLLBACK');throw e;}}
const get=(db,p)=>{const r=db.prepare('SELECT body FROM characters WHERE scope=?').get(key(p));return r&&decode(r.body);};
const put=(db,p,s)=>db.prepare('UPDATE characters SET body=? WHERE scope=?').run(encode(s),key(p));
const job=(db,p,id)=>{const r=db.prepare('SELECT body FROM jobs WHERE scope=? AND id=?').get(key(p),id);return r&&decode(r.body);};
const active=(db,p)=>db.prepare('SELECT id FROM jobs WHERE scope=? AND done=0').get(key(p));
const valid=(p,q)=>p&&q&&key(p)===key(q);
function setup(t){const dir=mkdtempSync(join(tmpdir(),'r143-')),path=join(dir,'test.sqlite'),db=open(path);db.exec('PRAGMA journal_mode=WAL; CREATE TABLE characters(scope TEXT PRIMARY KEY,body TEXT); CREATE TABLE backups(scope TEXT,id TEXT,body TEXT,PRIMARY KEY(scope,id)); CREATE TABLE jobs(scope TEXT,id TEXT,done INTEGER,body TEXT,PRIMARY KEY(scope,id)); CREATE UNIQUE INDEX one_active ON jobs(scope) WHERE done=0;');for(const p of [a,b,c]){const s={revision:3,items:['blade'],upgrade:{level:2,donorSpent:true},grants:[{id:'old',time:5},{id:'new',time:15}],pending:[]};db.prepare('INSERT INTO characters VALUES(?,?)').run(key(p),encode(s));db.prepare('INSERT INTO backups VALUES(?,?,?)').run(key(p),'before',encode({time:10,items:['blade','donor','old'],upgrade:{level:0,donorSpent:false}}));}t.after(()=>{db.close();rmSync(dir,{recursive:true,force:true});});return {db,path};}
// Trusted actor is synthetic harness input, not a client credential.
function start(db,actor,p,backupId,expected){if(!valid(actor,p))return {status:'unauthorized'};return tx(db,()=>{const id=encode([backupId,expected]),prior=job(db,p,id);if(prior)return {status:prior.stage===3?'complete':'pending',id};if(active(db,p))return {status:'busy'};const s=get(db,p),row=db.prepare('SELECT body FROM backups WHERE scope=? AND id=?').get(key(p),backupId);if(!s||!row)return {status:'missing'};if(s.revision!==expected)return {status:'conflict'};const j={stage:0,backup:decode(row.body),before:s};db.prepare('INSERT INTO jobs VALUES(?,?,0,?)').run(key(p),id,encode(j));return {status:'pending',id};});}
function step(db,actor,p,id,fail=false){if(!valid(actor,p))return 'unauthorized';return tx(db,()=>{const j=job(db,p,id);if(!j)return 'missing';if(j.stage===3)return 'complete';const s=get(db,p);if(j.stage===0){s.items=[...j.backup.items];s.revision++;}else if(j.stage===1){s.upgrade=structuredClone(j.backup.upgrade);}else{const ids=new Set([...s.items,...s.pending]);for(const g of s.grants)if(g.time>j.backup.time&&!ids.has(g.id)){s.pending.push(g.id);ids.add(g.id);}}j.stage++;put(db,p,s);db.prepare('UPDATE jobs SET body=?,done=? WHERE scope=? AND id=?').run(encode(j),Number(j.stage===3),key(p),id);if(fail)throw Error('injected rollback');return j.stage===3?'complete':'pending';});}
function visible(db,actor,p){if(!valid(actor,p))return {status:'unauthorized'};return tx(db,()=>active(db,p)?{status:'restoring'}:{status:'ready',state:get(db,p)});}
function deliver(db,actor,p){if(!valid(actor,p))return 'unauthorized';return tx(db,()=>{if(active(db,p))return 'busy';const s=get(db,p);if(!s.pending.length)return 'empty';s.items=[...new Set([...s.items,...s.pending])];s.pending=[];s.revision++;put(db,p,s);return 'delivered';});}
function finish(db,p,id){for(let i=0;i<3;i++)step(db,p,p,id);}
test('same restore request reuses journal; competing request blocked',t=>{const {db}=setup(t);const x=start(db,a,a,'before',3);assert.deepEqual(start(db,a,a,'before',3),x);assert.equal(start(db,a,a,'before',4).status,'busy');});
test('same owner different character cannot read or resume job',t=>{const {db}=setup(t);const x=start(db,a,a,'before',3);assert.equal(step(db,b,a,x.id),'unauthorized');assert.equal(step(db,b,b,x.id),'missing');assert.equal(visible(db,b,a).status,'unauthorized');});
test('different owner with same character label isolated',t=>{const {db}=setup(t);const x=start(db,a,a,'before',3);assert.equal(step(db,c,a,x.id),'unauthorized');assert.equal(step(db,c,c,x.id),'missing');assert.equal(visible(db,c,c).state.revision,3);});
test('independent characters can restore identical request ids',t=>{const {db}=setup(t);const x=start(db,a,a,'before',3),y=start(db,b,b,'before',3);assert.equal(x.id,y.id);finish(db,a,x.id);assert.equal(visible(db,a,a).status,'ready');assert.equal(visible(db,b,b).status,'restoring');finish(db,b,y.id);assert.equal(visible(db,b,b).state.upgrade.level,0);});
test('partial restore blocks reads and delivery; other character unaffected',t=>{const {db}=setup(t);const x=start(db,a,a,'before',3);step(db,a,a,x.id);assert.equal(visible(db,a,a).status,'restoring');assert.equal(deliver(db,a,a),'busy');assert.equal(visible(db,b,b).state.revision,3);});
test('each journal stage rolls back together with state on injected failure',t=>{const {db}=setup(t);const x=start(db,a,a,'before',3);for(let i=0;i<3;i++){const before=get(db,a);assert.throws(()=>step(db,a,a,x.id,true),/injected/);assert.deepEqual(get(db,a),before);assert.equal(job(db,a,x.id).stage,i);step(db,a,a,x.id);}assert.equal(visible(db,a,a).status,'ready');});
test('reopen after saved stage resumes upgrade and discovery reconciliation',t=>{const {db,path}=setup(t);const x=start(db,a,a,'before',3);step(db,a,a,x.id);const other=open(path);try{assert.equal(visible(other,a,a).status,'restoring');finish(other,a,x.id);const s=visible(other,a,a).state;assert.equal(s.revision,4);assert.deepEqual(s.upgrade,{level:0,donorSpent:false});assert.deepEqual(s.pending,['new']);assert.ok(s.items.includes('donor'));}finally{other.close();}});
test('completed restore replay does not rewind revision or duplicate delivery',t=>{const {db}=setup(t);const x=start(db,a,a,'before',3);finish(db,a,x.id);assert.equal(deliver(db,a,a),'delivered');assert.equal(deliver(db,a,a),'empty');assert.equal(start(db,a,a,'before',3).status,'complete');assert.equal(step(db,a,a,x.id),'complete');assert.equal(get(db,a).revision,5);assert.equal(get(db,a).items.filter(i=>i==='new').length,1);});
test('post-backup discovery already present or pending is not duplicated',t=>{const {db}=setup(t);const s=get(db,a);s.pending=['new'];put(db,a,s);const x=start(db,a,a,'before',3);finish(db,a,x.id);assert.deepEqual(get(db,a).pending,['new']);assert.equal(deliver(db,a,a),'delivered');assert.equal(get(db,a).items.filter(i=>i==='new').length,1);});
test('wrong backup and stale revision leave no journal',t=>{const {db}=setup(t);assert.equal(start(db,a,a,'unknown',3).status,'missing');assert.equal(start(db,a,a,'before',2).status,'conflict');assert.equal(active(db,a),undefined);assert.equal(get(db,a).revision,3);});
